import sys, os, json, random, subprocess, pathlib; sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace')
from harness import *
from wire import envelope, stream, crypto, datagram, trace, v
build()
TAP = pathlib.Path('/workspace/tmp/canon.tap'); LOG = pathlib.Path('/workspace/tmp/canon.log')
TAP.write_text('')
def consistent(off,n): return bytes(((off+i)*7+3)&0xff for i in range(n))

def run_logged(traces):
    if LOG.exists(): LOG.unlink()
    data = json.dumps({'traces': traces}).encode()
    p = subprocess.run(['python3','/workspace/run.py','/workspace/tmp/classes'], input=data, capture_output=True)
    assert p.returncode==0, p.stderr.decode()[:2000]
    lines = LOG.read_text().split() if LOG.exists() else []
    return json.loads(p.stdout), [bytes.fromhex(x) for x in lines]

random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 5)
def gen_trace(seed):
    random.seed(seed)
    events=[{'keys':['I','H','A']}]
    ann=[]
    pn={'I':0,'H':0,'A':0}
    cur=0
    for e in range(60):
        bodies=[]
        for f in range(random.randint(1,6)):
            k=random.randrange(9)
            sid=random.choice([0,4,8,2,6,1,3])
            if k==0:
                off=random.randrange(0,300)*4; n=random.randrange(0,50)
                fin = random.random()<0.15
                bodies.append(stream(sid, off, consistent(off,n), fin=fin, offset=random.random()<0.8, length=random.random()<0.8))
            elif k==1:
                off=random.randrange(0,300)*4; n=random.randrange(0,50); bodies.append(crypto(off, consistent(off,n)))
            elif k==2:
                lg=random.randrange(0,200); bodies.append(bytes([random.choice([2,3])])+v(lg,random.choice([1,2,4]))+v(random.randrange(5),2)+v(0)+v(random.randrange(0,lg+1)))
                if random.random()<0.3: bodies[-1]+=v(1)+v(2)+v(3) if bodies[-1][0]==3 else b''
            elif k==3: bodies.append(b'\x00'*random.randrange(1,5)+b'\x01')
            elif k==4: bodies.append(b'\x10'+v(random.randrange(0,10**6),random.choice([1,4])))
            elif k==5: bodies.append(b'\x15'+v(sid)+v(0))
            elif k==6: bodies.append(b'\x11'+v(sid if sid%4!=2 else 0)+v(random.randrange(10**4)))
            elif k==7: bodies.append(b'\x18'+v(random.randrange(1,3))+v(0)+b'\x01'+bytes([0xd0+random.randrange(1,3)])+b'\x22'*16)
            else: bodies.append(random.choice([b'\x14'+v(3), b'\x16'+v(2), b'\x17'+v(1), b'\x1a'+b'12345678', b'\x31'+v(2)+b'xy', b'\x05'+v(0 if sid%4==2 else sid)+v(3)]))
        lvl=random.choice(['I','H','A'])
        if lvl!='A':
            # only level-legal frames
            bodies=[b for b in bodies if b[:1] in (b'\x00',b'\x01',b'\x02',b'\x03',b'\x06')] or [b'\x01']
        body=b''.join(bodies)
        width=random.choice([1,2,4])
        w=envelope(lvl, pn[lvl], body, width=width, cid=random.choice([b'\xaa',b'\xbb']), phase=random.randrange(2) if lvl=='A' else 0)
        g = 0
        if lvl=='A':
            ph=(w[0]>>2)&1
            g = cur+1 if (ph!=(cur&1)) and random.random()<0.3 else cur
            if (g&1)!=ph: g=cur if (cur&1)==ph else cur+1
            if lvl=='A' and g==cur+1: cur=g
        pn[lvl]+=1
        events.append(datagram(w, auth=(g,)))
        ann.append((lvl,g))
    return trace(events, connection=2**62-1, stream_credit=2**62-1, cids=4)

traces=[gen_trace(1000+i) for i in range(6)]
out1, canon1 = run_logged(traces)
acc1=[(t,p) for t in out1['traces'] for p in t['packets'] if p['status'] in ('OK','PEER_CLOSE')]
print('accepted packets', len(acc1), 'canonical envelopes', len(canon1))
assert len(acc1)==len(canon1)
# replay: one datagram per accepted canonical envelope, same annotation
events=[]; 
i=0
for t in out1['traces']:
    for p in t['packets']:
        if p['status'] in ('OK','PEER_CLOSE'):
            g = 0 if p['level'] in ('I','H') else p['epoch']
            events.append(datagram(canon1[i], auth=(g,))); i+=1
    # per trace boundary: just replay all in one trace (same config)
out2, canon2 = run_logged([trace([{'keys':['I','H','A']}]+events)])
acc2=[p for t in out2['traces'] for p in t['packets'] if p['status'] in ('OK','PEER_CLOSE')]
print('replay accepted', len(acc2), 'canon2', len(canon2))
print('canon identical:', canon2==canon1)
if canon2!=canon1:
    for a,b in zip(canon1,canon2):
        if a!=b: print('DIFF', a.hex(), b.hex()); break
print('statuses1', json.dumps([p['status'] for t in out1['traces'] for p in t['packets']][:20]))
print('statuses2', json.dumps([p['status'] for t in out2['traces'] for p in t['packets']][:20]))
